<script setup lang="ts">
import {ask,confirmation,finishConfirmation} from './confirm';
import {ref,onMounted,onUnmounted,computed} from 'vue';import {api,setCSRF} from './api';import Devices from './Devices.vue';import Users from './Users.vue';import Records from './Records.vue';import ProjectView from './ProjectView.vue';import Dialog from './Dialog.vue';
const user=ref<any>(null),loading=ref(true),username=ref(''),password=ref(''),loginError=ref(''),busy=ref(false),section=ref('projects'),projects=ref<any[]>([]),selected=ref<any>(null),projectEdit=ref<any>(null),error=ref(''),message=ref(''),baseURL=ref(''),menu=ref(false),passwordDialog=ref(false),oldPassword=ref(''),newPassword=ref('');
const admin=computed(()=>user.value?.role==='admin');let messageTimer:ReturnType<typeof setTimeout>;
function notify(text:string){message.value=text;clearTimeout(messageTimer);messageTimer=setTimeout(()=>message.value='',8000)}
async function me(){const r=await api('/auth/me');user.value=r.user;setCSRF(r.csrf);baseURL.value=r.public_base_url||location.origin}
async function loadProjects(){try{projects.value=await api(admin.value?'/admin/projects':'/projects');if(selected.value){selected.value=projects.value.find(p=>p.id===selected.value.id)||null}}catch(e:any){notify(e.message)}}
function route(){const parts=location.pathname.split('/').filter(Boolean);section.value=['devices','users','records'].includes(parts[0])?parts[0]:'projects';if(!admin.value&&section.value!=='projects')section.value='projects';selected.value=parts[0]==='projects'&&parts[1]?projects.value.find(p=>p.key===parts[1])||null:null;menu.value=false}
function navigate(s:string){history.pushState({},'','/'+s);route()}
function openProject(p:any){history.pushState({},'','/projects/'+p.key);route()}
async function login(){busy.value=true;loginError.value='';try{const r=await api('/auth/login','POST',{username:username.value,password:password.value});user.value=r.user;setCSRF(r.csrf);password.value='';await me();await loadProjects();route()}catch(e:any){loginError.value=e.message}finally{busy.value=false}}
async function logout(){try{await api('/auth/logout','POST',{})}catch{}user.value=null;selected.value=null;projects.value=[];setCSRF('');navigate('projects')}
function expired(){user.value=null;selected.value=null;projects.value=[];setCSRF('');}
onMounted(async()=>{window.addEventListener('session-expired',expired);try{await me();await loadProjects();route()}catch{}finally{loading.value=false};window.addEventListener('popstate',route)});onUnmounted(()=>{window.removeEventListener('popstate',route);window.removeEventListener('session-expired',expired);clearTimeout(messageTimer)});
function create(){error.value='';projectEdit.value={key:'',display_name:'',purpose:'',usage_instructions:'',notes:'',enabled:true}}
function editing(p:any){error.value='';projectEdit.value={...p}}
async function save(){busy.value=true;error.value='';try{const p=projectEdit.value;await api('/admin/projects'+(p.id?'/'+p.id:''),p.id?'PATCH':'POST',p);projectEdit.value=null;await loadProjects();notify('项目已保存')}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function remove(p:any){if(!await ask('删除项目“'+p.display_name+'”？服务入口将失效，项目Token将撤销，调用审计保留；物理设备输出不会改变。'))return;try{await api('/admin/projects/'+p.id,'DELETE');await loadProjects();notify('项目已删除')}catch(e:any){notify(e.message)}}
async function changePassword(){busy.value=true;error.value='';try{await api('/auth/password','PUT',{old_password:oldPassword.value,password:newPassword.value});passwordDialog.value=false;oldPassword.value='';newPassword.value='';user.value=null;setCSRF('');notify('密码已修改，请重新登录')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div v-if="loading" class="loading">正在加载设备控制台…</div><div v-else-if="!user" class="login-layout"><div class="login-story"><div class="brand"><span class="brand-symbol">◈</span><span>设备服务控制台<small>DEVICE SERVICE PLATFORM</small></span></div><div><p class="eyebrow">CONNECT. DEFINE. OPERATE.</p><h1>让设备能力，<br>成为项目服务。</h1><p>统一接入设备，以稳定接口连接实验与开发。</p><div class="signal-lines"><span/><span/><span/><span/><span/></div></div><span class="meta">通用设备接入 · 项目命名服务 · 实时操作与采集</span></div><main class="login-main"><form class="login-card" @submit.prevent="login"><span class="badge">工作台登录</span><h2>欢迎回来</h2><p class="muted">使用管理员或项目成员账号登录。</p><label>用户名<input v-model="username" autocomplete="username" required autofocus placeholder="请输入用户名"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required placeholder="请输入密码"></label><p v-if="loginError" class="error-text" role="alert">{{loginError}}</p><button class="primary" :disabled="busy">{{busy?'登录中…':'登录控制台 →'}}</button><p class="meta">首次使用请通过本机 CLI 初始化管理员。</p></form></main></div>
<div v-else class="app-shell"><aside class="sidebar" :class="{expanded:menu}"><div class="brand"><span class="brand-symbol">◈</span><span>设备服务控制台<small>DEVICE SERVICE PLATFORM</small></span></div><button class="mobile-menu" :aria-expanded="menu" aria-label="展开导航" @click="menu=!menu">☰</button><nav class="main-nav" aria-label="主导航"><span class="nav-label">工作空间</span><button :class="{active:section==='projects'}" @click="navigate('projects')"><span>▦</span> 项目服务</button><button v-if="admin" :class="{active:section==='devices'}" @click="navigate('devices')"><span>⌁</span> 设备管理</button><button v-if="admin" :class="{active:section==='records'}" @click="navigate('records')"><span>≡</span> 调用记录</button><span v-if="admin" class="nav-label">平台管理</span><button v-if="admin" :class="{active:section==='users'}" @click="navigate('users')"><span>♧</span> 用户管理</button></nav><div class="sidebar-footer"><span class="dot online"/> 服务已连接 <small>Linux / amd64</small></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">工作空间 <span>/</span> {{({projects:'项目服务',devices:'设备管理',records:'调用记录',users:'用户管理'} as any)[section]}}</span><div class="account"><span class="avatar">{{user.username.slice(0,1).toUpperCase()}}</span><span>{{user.username}}<small>{{admin?'管理员':'项目成员'}}</small></span><button class="text-button" @click="passwordDialog=true;error=''">改密</button><button class="text-button" @click="logout">退出</button></div></header><main class="main-content"><Devices v-if="section==='devices'&&admin" @message="notify"/><Users v-else-if="section==='users'&&admin" @message="notify"/><Records v-else-if="section==='records'&&admin" :admin="admin" @message="notify"/><ProjectView v-else-if="selected" :project="selected" :admin="admin" :baseURL="baseURL" @message="notify" @changed="loadProjects" @back="navigate('projects')"/><section v-else><div class="section-title"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>项目服务</h1><p class="muted">按项目组织设备能力，为人工与 Agent 提供稳定入口。</p></div><button v-if="admin" class="primary" @click="create">＋ 创建项目</button></div><div class="stat-strip"><span><b>{{projects.length}}</b> 个项目</span><span><i class="dot online"/> {{projects.filter(p=>p.enabled).length}} 个已启用</span><button class="text-button" @click="loadProjects">刷新列表 ↻</button></div><div v-if="!projects.length" class="empty"><div class="empty-symbol">▦</div><h2>{{admin?'创建第一个项目':'尚未获得项目授权'}}</h2><p>{{admin?'定义业务用途，绑定设备服务，再将文档和 Token 交给调用方。':'请联系管理员，将你的账号加入项目成员。'}}</p><button v-if="admin" class="primary" @click="create">创建项目</button></div><div class="card-grid"><article v-for="p in projects" :key="p.id" class="card project-card"><div class="row spread"><span class="project-mark">▦</span><span class="badge" :class="p.enabled?'online':'error'">{{p.enabled?'已启用':'已禁用'}}</span></div><h2>{{p.display_name}}</h2><code>{{p.key}}</code><p class="description">{{p.purpose||'尚未填写项目用途'}}</p><div class="card-actions"><button class="primary" @click="openProject(p)">进入项目 →</button><button v-if="admin" @click="editing(p)">编辑</button><button v-if="admin" class="text-button danger" @click="remove(p)">删除</button></div></article></div><div class="workspace-note"><strong>从设备到业务的稳定连接</strong><p>设备连接由平台管理，项目服务保留稳定名称。多个项目可共享设备，通信冲突会立即明确返回。</p></div></section></main><footer class="page-footer"><span>设备服务控制台</span><span>通用接入 · 明确契约 · 可追溯调用</span></footer></div></div>
<div v-if="message" class="toast" role="status"><span>{{message}}</span><button aria-label="关闭提示" @click="message=''">×</button></div>
<Dialog v-if="projectEdit" :title="projectEdit.id?'编辑项目':'创建项目'" @close="if(!busy)projectEdit=null;"><form @submit.prevent="save"><div class="two-columns"><label>项目标识<input v-model="projectEdit.key" required pattern="[a-z](?:[a-z0-9_]|-){0,63}" :disabled="!!projectEdit.id" placeholder="board-test-a"></label><label>显示名称<input v-model="projectEdit.display_name" required placeholder="板卡测试项目"></label></div><label>项目用途<textarea v-model="projectEdit.purpose" rows="3" placeholder="描述业务背景与目标"/></label><label>推荐操作步骤<textarea v-model="projectEdit.usage_instructions" rows="3"/></label><label>注意事项<textarea v-model="projectEdit.notes" rows="2"/></label><label class="check-row"><input v-model="projectEdit.enabled" type="checkbox">启用项目</label><p v-if="error" class="error-text" role="alert">{{error}}</p><footer class="form-actions"><button type="button" @click="projectEdit=null" :disabled="busy">取消</button><button class="primary" :disabled="busy">保存项目</button></footer></form></Dialog>
<Dialog v-if="passwordDialog" title="修改本人密码" @close="if(!busy)passwordDialog=false;"><form @submit.prevent="changePassword"><label>原密码<input v-model="oldPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="10" required></label><p class="muted">修改后当前账号的所有会话失效，需要重新登录。</p><p v-if="error" class="error-text" role="alert">{{error}}</p><footer class="form-actions"><button class="primary" :disabled="busy">修改密码</button></footer></form></Dialog>
<Dialog v-if="confirmation.message" title="确认操作" @close="finishConfirmation(false)"><p>{{confirmation.message}}</p><footer class="form-actions"><button @click="finishConfirmation(false)">取消</button><button class="primary" @click="finishConfirmation(true)">确认操作</button></footer></Dialog>
</template>
